class MagicDictionary { private final Map<Integer,List<String>> words=new HashMap<>();public MagicDictionary(){}public void buildDict(String[] dictionary){for(String word:dictionary)words.computeIfAbsent(word.length(),key->new ArrayList<>()).add(word);}public boolean search(String searchWord){for(String word:words.getOrDefault(searchWord.length(),Collections.emptyList())){int differences=0;for(int i=0;i<word.length()&&differences<=1;i++)if(word.charAt(i)!=searchWord.charAt(i))differences++;if(differences==1)return true;}return false;} }
